-- Publish through the canonical guard path (draft -> active with content receipt).
DO $$
DECLARE v_id uuid; v_receipt jsonb; v_state text;
BEGIN
  SELECT catalog_version_id, lifecycle_state INTO v_id, v_state FROM public.curriculum_catalog_versions
   WHERE version_key = 'success-path-catalog-v1';
  IF v_state = 'draft' THEN
    v_receipt := public.publish_curriculum_catalog_version(v_id);
    IF v_receipt->>'content_sha256' IS NULL OR length(v_receipt->>'content_sha256') <> 64 THEN
      RAISE EXCEPTION 'catalog publish did not return a content receipt';
    END IF;
  END IF;
END $$;

COMMIT;